import fs from 'fs';
import os from 'os';
import path from 'path';

import { escapeHtml, pageTitle, renderIndex, renderPage } from '../render';
import { buildSite, listMarkdownFiles, loadPages, readPage, slugify } from '../site';
import type { Page } from '../types';

const SAMPLE_MD = `---
title: Sample
date: 2026-05-01
tags: demo, test
---

# Heading

Some <b>body</b> content.
`;

describe('slugify', () => {
  it('strips the file extension', () => {
    expect(slugify('hello-world.md')).toBe('hello-world');
    expect(slugify('guide.md')).toBe('guide');
  });
});

describe('listMarkdownFiles', () => {
  it('returns only Markdown files', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-'));
    fs.writeFileSync(path.join(dir, 'a.md'), '# a');
    fs.writeFileSync(path.join(dir, 'b.MD'), '# b');
    fs.writeFileSync(path.join(dir, 'notes.txt'), 'hi');

    const files = listMarkdownFiles(dir);
    expect(files).toEqual(['a.md', 'b.MD']);
  });

  it('returns an empty list for a missing directory', () => {
    expect(listMarkdownFiles(path.join(os.tmpdir(), 'does-not-exist-ssg'))).toEqual([]);
  });
});

describe('loadPages', () => {
  it('reads, parses and sorts Markdown files into pages', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-'));
    fs.writeFileSync(path.join(dir, 'b.md'), SAMPLE_MD);
    fs.writeFileSync(path.join(dir, 'a.md'), '---\ntitle: Alpha\n---\nContent A.');

    const pages = loadPages(dir);
    expect(pages).toHaveLength(2);
    expect(pages[0].slug).toBe('a');
    expect(pages[1].slug).toBe('b');
    expect(pages[1].title).toBe('Sample');
    expect(pages[1].date).toBe('2026-05-01');
    expect(pages[1].tags).toEqual(['demo', 'test']);
    expect(pages[1].outputName).toBe('b.html');
    expect(pages[1].html).toContain('<h1');
  });
});

describe('readPage', () => {
  it('falls back to the slug when no title is provided', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-'));
    fs.writeFileSync(path.join(dir, 'untitled.md'), '# Body');
    const page = readPage('untitled.md', dir);
    expect(page.title).toBe('untitled');
  });
});

describe('buildSite', () => {
  let contentDir: string;
  let outputDir: string;

  beforeEach(() => {
    contentDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-content-'));
    outputDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-dist-'));
  });

  afterEach(() => {
    fs.rmSync(contentDir, { recursive: true, force: true });
    fs.rmSync(outputDir, { recursive: true, force: true });
  });

  // Point at a non-existent templates directory so these tests exercise the
  // built-in renderers regardless of whether ./templates exists in the repo.
  const missingTemplatesDir = () => path.join(outputDir, 'missing-templates');

  it('writes a page html file and an index.html', () => {
    fs.writeFileSync(path.join(contentDir, 'first.md'), SAMPLE_MD);

    const pages = buildSite({ contentDir, outputDir, templatesDir: missingTemplatesDir() });

    expect(pages).toHaveLength(1);
    expect(fs.existsSync(path.join(outputDir, 'first.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);

    const pageHtml = fs.readFileSync(path.join(outputDir, 'first.html'), 'utf8');
    expect(pageHtml).toContain('<h1>Sample</h1>');
    expect(pageHtml).toContain('>2026-05-01</p>');
    expect(pageHtml).toContain('class="tag">demo');
    expect(pageHtml).toContain('Some <b>body</b> content.');

    const indexHtml = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf8');
    expect(indexHtml).toContain('href="first.html"');
    expect(indexHtml).toContain('Sample');
  });

  it('escapes frontmatter-derived values in generated HTML', () => {
    fs.writeFileSync(
      path.join(contentDir, 'x.md'),
      '---\ntitle: <script>alert(1)</script>\n---\nBody'
    );

    buildSite({ contentDir, outputDir, templatesDir: missingTemplatesDir() });

    const pageHtml = fs.readFileSync(path.join(outputDir, 'x.html'), 'utf8');
    expect(pageHtml).toContain('&lt;script&gt;alert(1)&lt;/script&gt;');
    expect(pageHtml).not.toContain('<script>alert(1)</script>');
  });

  it('writes one file per page plus the index', () => {
    fs.writeFileSync(path.join(contentDir, 'one.md'), SAMPLE_MD);
    fs.writeFileSync(path.join(contentDir, 'two.md'), '---\ntitle: Two\n---\nBody');

    buildSite({ contentDir, outputDir, templatesDir: missingTemplatesDir() });

    const files = fs.readdirSync(outputDir).sort();
    expect(files).toEqual(['index.html', 'one.html', 'two.html']);
  });

  it('creates the output directory when missing', () => {
    const nested = path.join(outputDir, 'missing', 'site');
    fs.writeFileSync(path.join(contentDir, 'one.md'), SAMPLE_MD);

    buildSite({ contentDir, outputDir: nested, templatesDir: missingTemplatesDir() });
    expect(fs.existsSync(path.join(nested, 'index.html'))).toBe(true);
  });

  it('handles an empty content directory', () => {
    const pages = buildSite({ contentDir, outputDir, templatesDir: missingTemplatesDir() });
    expect(pages).toHaveLength(0);
    const indexHtml = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf8');
    expect(indexHtml).toContain('No pages yet.');
  });
});

describe('render helpers', () => {
  it('escapeHtml escapes HTML-sensitive characters', () => {
    expect(escapeHtml('<b>&"\'>')).toBe('&lt;b&gt;&amp;&quot;&#39;&gt;');
  });

  it('pageTitle uses frontmatter title or a fallback', () => {
    expect(pageTitle({ title: 'T' }, 'fallback')).toBe('T');
    expect(pageTitle({ title: '  ' }, 'fallback')).toBe('fallback');
    expect(pageTitle({}, 'fallback')).toBe('fallback');
  });

  it('renderPage includes the page content and index link', () => {
    const page: Page = {
      slug: 'x',
      sourcePath: 'x.md',
      outputName: 'x.html',
      title: 'X',
      date: '2026-01-01',
      tags: ['t'],
      html: '<p>hello</p>',
      content: 'hello',
      raw: 'hello',
      data: { title: 'X', date: '2026-01-01', tags: ['t'] },
    };
    const html = renderPage(page);
    expect(html).toContain('<title>X</title>');
    expect(html).toContain('<p>hello</p>');
    expect(html).toContain('href="index.html"');
  });

  it('renderIndex lists all pages with links', () => {
    const pages: Page[] = [
      {
        slug: 'a',
        sourcePath: 'a.md',
        outputName: 'a.html',
        title: 'A',
        tags: [],
        html: '',
        content: '',
        raw: '',
        data: { title: 'A' },
      },
      {
        slug: 'b',
        sourcePath: 'b.md',
        outputName: 'b.html',
        title: 'B',
        date: '2026-01-01',
        tags: ['x', 'y'],
        html: '',
        content: '',
        raw: '',
        data: { title: 'B', date: '2026-01-01', tags: ['x', 'y'] },
      },
    ];
    const html = renderIndex(pages);
    expect(html).toContain('href="a.html">A</a>');
    expect(html).toContain('href="b.html">B</a>');
    expect(html).toContain('>2026-01-01</span>');
  });
});

/**
 * Template engine support built on Handlebars.
 *
 * Expected directory layout:
 *
 *   templates/            page templates; `default.hbs` is used when a page
 *                         does not declare a template in its frontmatter
 *   templates/layouts/    layout templates that wrap page output through the
 *                         `{{{body}}}` placeholder
 *   templates/partials/   reusable partials (e.g. header, footer, nav)
 *
 * Pages may declare a `template` and a `layout` in their frontmatter, either
 * with or without the `.hbs` extension. If a templates directory exists, every
 * page is rendered through its template and then wrapped in its layout; the
 * site index uses `index.hbs` (falling back to the built-in index renderer).
 */

import fs from 'fs';
import path from 'path';

import Handlebars from 'handlebars';

import type { Page } from './types';

/** Name of the template used when a page does not declare one. */
export const DEFAULT_TEMPLATE = 'default';
/** Name of the layout used when a page does not declare one. */
export const DEFAULT_LAYOUT = 'default';
/** Default directory searched for templates, layouts and partials. */
export const DEFAULT_TEMPLATES_DIR = 'templates';
/** File extension used by template files. */
export const TEMPLATE_EXTENSION = 'hbs';

/** Loaded and compiled template assets. */
export interface Templates {
  /** Path of the templates directory these were loaded from. */
  dir: string;
  /** Compiled page templates keyed by file name. */
  templates: Map<string, Handlebars.TemplateDelegate>;
  /** Compiled layout templates keyed by file name. */
  layouts: Map<string, Handlebars.TemplateDelegate>;
  /** Compiled partials keyed by name (file name without extension). */
  partials: Map<string, Handlebars.TemplateDelegate>;
}

/** Context available to templates and layouts while rendering a page. */
export interface TemplateContext extends Record<string, unknown> {
  title: string;
  date?: string;
  tags: string[];
  /** Rendered Markdown body of the page. */
  body: string;
  /** Raw Markdown body of the page. */
  content: string;
  slug: string;
  outputName: string;
}

/** List `.hbs` template files (non-recursive) inside a directory. */
function listTemplateFiles(dir: string): string[] {
  if (!fs.existsSync(dir)) return [];
  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter(
      (entry) =>
        entry.isFile() &&
        new RegExp(`\\.${TEMPLATE_EXTENSION}$`, 'i').test(entry.name),
    )
    .map((entry) => entry.name)
    .sort();
}

/** Whether a templates directory exists at the given path. */
export function hasTemplates(templatesDir: string): boolean {
  return fs.existsSync(templatesDir);
}

/**
 * Load every template, layout and partial found under `templatesDir`.
 * Partials are registered on a private Handlebars environment keyed by their
 * file name without the extension, so templates and layouts can reference them
 * with `{{> name}}`.
 */
export function loadTemplates(templatesDir: string): Templates {
  const engine = Handlebars.create();

  const templates = new Map<string, Handlebars.TemplateDelegate>();
  const layouts = new Map<string, Handlebars.TemplateDelegate>();
  const partials = new Map<string, Handlebars.TemplateDelegate>();

  for (const name of listTemplateFiles(templatesDir)) {
    templates.set(
      name,
      engine.compile(fs.readFileSync(path.join(templatesDir, name), 'utf8')),
    );
  }

  const layoutsDir = path.join(templatesDir, 'layouts');
  for (const name of listTemplateFiles(layoutsDir)) {
    layouts.set(
      name,
      engine.compile(fs.readFileSync(path.join(layoutsDir, name), 'utf8')),
    );
  }

  const partialsDir = path.join(templatesDir, 'partials');
  for (const name of listTemplateFiles(partialsDir)) {
    const compiled = engine.compile(
      fs.readFileSync(path.join(partialsDir, name), 'utf8'),
    );
    const partialName = path.basename(name, path.extname(name));
    partials.set(partialName, compiled);
    engine.registerPartial(partialName, compiled);
  }

  return { dir: templatesDir, templates, layouts, partials };
}

/** Normalise a template/layout name into a file name with an extension. */
export function resolveTemplateName(
  name: string,
  extension = TEMPLATE_EXTENSION,
): string {
  const trimmed = name.trim();
  return new RegExp(`\\.${extension}$`, 'i').test(trimmed)
    ? trimmed
    : `${trimmed}.${extension}`;
}

/** Build the render context for a page. */
export function pageContext(page: Page): TemplateContext {
  return {
    ...page.data,
    title: page.title,
    date: page.date,
    tags: page.tags,
    body: page.html,
    content: page.content,
    slug: page.slug,
    outputName: page.outputName,
  };
}

/** Render a compiled template file from the templates or layouts directory. */
export function renderTemplateFile(
  templates: Templates,
  kind: 'templates' | 'layouts',
  name: string,
  context: Record<string, unknown>,
): string {
  const compiled =
    kind === 'layouts' ? templates.layouts.get(name) : templates.templates.get(name);
  if (!compiled) {
    throw new Error(`Template not found: ${kind}/${name}`);
  }
  return compiled(context);
}

/** Resolve the template file a page should use, falling back to the default. */
function pageTemplateName(page: Page): string {
  const declared = page.data.template;
  const name =
    typeof declared === 'string' && declared.trim() ? declared : DEFAULT_TEMPLATE;
  return resolveTemplateName(name);
}

/** Resolve the layout file a page should use, falling back to the default. */
function pageLayoutName(page: Page): string {
  const declared = page.data.layout;
  const name =
    typeof declared === 'string' && declared.trim() ? declared : DEFAULT_LAYOUT;
  return resolveTemplateName(name);
}

/**
 * Render a full page: first through its page template, then wrapped in its
 * layout using the `{{{body}}}` placeholder.
 */
export function renderPageWithTemplates(page: Page, templates: Templates): string {
  const context = pageContext(page);

  const content = renderTemplateFile(
    templates,
    'templates',
    pageTemplateName(page),
    context,
  );
  return renderTemplateFile(templates, 'layouts', pageLayoutName(page), {
    ...context,
    body: content,
  });
}

/** Render the site index through the `index` template and the default layout. */
export function renderIndexWithTemplates(pages: Page[], templates: Templates): string {
  const context = {
    title: 'Index',
    pages: pages.map((page) => pageContext(page)),
  };

  const body = renderTemplateFile(
    templates,
    'templates',
    `index.${TEMPLATE_EXTENSION}`,
    context,
  );
  return renderTemplateFile(templates, 'layouts', resolveTemplateName(DEFAULT_LAYOUT), {
    ...context,
    body,
  });
}

