const log=(m)=>{fs.appendFileSync('/tmp/probe.log', m+'\n');};
const get=(port,p)=>new Promise((res,rej)=>{const r=http.get({hostname:'127.0.0.1',port,path:p,agent:false,headers:{Connection:'close'}},(resp)=>{let b='';resp.on('data',c=>b+=c);resp.on('end',()=>res(b));});r.on('error',rej);});
(async () => {
  const contentDir=fs.mkdtempSync(path.join(os.tmpdir(),'probe-content-'));
  const outputDir=fs.mkdtempSync(path.join(os.tmpdir(),'probe-dist-'));
  fs.writeFileSync(path.join(contentDir,'a.md'),'# A');
  const dev=await startDevServer({contentDir,outputDir,templatesDir:path.join(outputDir,'mt'),port:0});
  await get(dev.port,'/a.html');
  const client=new WebSocket('ws://127.0.0.1:'+dev.port+'/__ssg_reload');
  await new Promise((res,rej)=>{client.on('open',res);client.on('error',rej);});
  log('connected; closing...');
  await dev.close();
  client.terminate();
  log('closed; checking handles');
  setTimeout(()=>{
    const names=process._getActiveHandles().map(h=>h.constructor&&h.constructor.name);
    log('handles: '+JSON.stringify(names));
    process.exit(0);
  },1000);
})();
