const http=require('http');
const net=require('net');
const crypto=require('crypto');
const WebSocket=require('ws');
const fs=require('fs');
const log=(m)=>{fs.appendFileSync('/tmp/probe.log', m+'\n');};
const sockInfo=()=>process._getActiveHandles().filter(h=>h.constructor&&h.constructor.name==='Socket').map(h=>(h._handle&&h._handle.constructor.name));
(async () => {
  const server=http.createServer((req,res)=>res.end('x'));
  const wss=new WebSocket.WebSocketServer({server, path:'/ws'});
  await new Promise(r=>server.listen(0,r));
  const port=server.address().port;
  // raw net client doing the upgrade handshake
  const raw = new Promise((resolve, reject) => {
    const sock = net.connect(port, '127.0.0.1', () => {
      const key = crypto.randomBytes(16).toString('base64');
      sock.write('GET /ws HTTP/1.1\r\nHost: 127.0.0.1\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: '+key+'\r\nSec-WebSocket-Version: 13\r\n\r\n');
    });
    let buf='';
    sock.on('data', (d)=>{ buf+=d.toString(); if(buf.includes('\r\n\r\n')) { log('upgrade response: '+buf.split('\r\n')[0]); sock.destroy(); resolve(); } });
    sock.on('error', reject);
  });
  await raw;
  log('after raw client closed: '+JSON.stringify(sockInfo()));
  for (const c of wss.clients) c.terminate();
  wss.close();
  await new Promise(r=>server.close(r));
  setTimeout(()=>{ log('t+1000: '+JSON.stringify(sockInfo())); process.exit(0); },1000);
})();
