it('broadcasts a reload message over the WebSocket when files change', async () => {
  const server = await startServer();
  const client = new WebSocket(
    `ws://127.0.0.1:${server.dev.port}${RELOAD_PATH}`,
  );
  try {
    await new Promise<void>((resolve, reject) => {
      client.on('open', () => resolve());
      client.on('error', (err) => reject(err));
    });

    const messages: string[] = [];
    client.on('message', (data) => messages.push(data.toString()));

    await delay(200);
    fs.writeFileSync(path.join(server.contentDir, 'third.md'), '# Third');

    await waitFor(() => messages.some((message) => message.includes('reload')));
  } finally {
    client.terminate();
    await stopServer(server);
  }
});

it('closes the server, watcher and WebSocket cleanly', async () => {
  const server = await startServer();
  try {
    const client = new WebSocket(
      `ws://127.0.0.1:${server.dev.port}${RELOAD_PATH}`,
    );
    await new Promise<void>((resolve, reject) => {
      client.on('open', () => resolve());
      client.on('error', (err) => reject(err));
    });

    await server.dev.close();
    expect(server.dev.server.listening).toBe(false);
  } finally {
    await stopServer(server);
  }
});

